import os,re,json
from collections import defaultdict
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
pairs=[(G[f'Demo pair {k} input'],G[f'Demo pair {k} output']) for k in [1,2,3]]
for idx,(i,o) in enumerate(pairs):
    cells=[(r,c) for r in range(7) for c in range(7) if i[r][c]==8]
    rs=[r for r,_ in cells]; cs=[c for _,c in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    # centroid of shape cells
    M=sum(r for r,c in cells)/len(cells); N=sum(c for r,c in cells)/len(cells)
    cnt=defaultdict(set)
    for r,c in cells:
        kv={'TL' if r<M else 'BL': 'L' if c<N else 'R'}
        kv=f"{kv[r<M and c<N]}{kv[r<M and c>=N]}"
        cnt[kv].add(o[r][c])
    print(f'pair{idx}: centroid={M:.2f},{N:.2f}')
    for k,v in sorted(cnt.items()): print(' ',k,v)

